+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H2;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.data.provider.Query;
+import com.vaadin.flow.router.NavigationTrigger;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.theme.lumo.LumoUtility;
+
+import java.util.stream.Collectors;
+import java.util.stream.Stream;
+
+/** UC-002: View Veterinarians. */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VetsView extends VerticalLayout {
+
+    private final transient VetRepository repository;
+
+    public VetsView(VetRepository repository) {
+        this.repository = repository;
+        setSizeFull();
+
+        H2 heading = new H2("Veterinarians");
+        heading.addClassNames(LumoUtility.Margin.NONE);
+        Grid<Vet> grid = new Grid<>();
+        grid.setSizeFull();
+        grid.setSelectionMode(Grid.SelectionMode.NONE);
+        grid.getElement().setAttribute("aria-label", "Veterinarians");
+        grid.addColumn(Vet::firstName).setHeader("First Name").setKey("firstName");
+        grid.addColumn(Vet::lastName).setHeader("Last Name").setKey("lastName");
+        grid.addColumn(vet -> vet.specialties().isEmpty() ? "none" : vet.specialties().stream()
+                .map(Specialty::name).collect(Collectors.joining(", ")))
+                .setHeader("Specialties").setKey("specialties");
+        grid.setItems(this::fetch, this::count);
+        add(heading, grid);
+        expand(grid);
+    }
+
+    private Stream<Vet> fetch(Query<Vet, Void> query) {
+        try {
+            return repository.findPage(query.getOffset(), query.getLimit());
+        } catch (RuntimeException exception) {
+            showError(exception);
+            return Stream.empty();
+        }
+    }
+
+    private int count(Query<Vet, Void> query) {
+        try {
+            return repository.count();
+        } catch (RuntimeException exception) {
+            showError(exception);
+            return 0;
+        }
+    }
+
+    private void showError(RuntimeException exception) {
+        // Lazy callbacks also run after navigation, outside the router's usual error handling.
+        UI ui = UI.getCurrent();
+        ui.getInternals().getRouter().handleExceptionNavigation(ui,
+                ui.getInternals().getActiveViewLocation(), exception, NavigationTrigger.PROGRAMMATIC, null);
+    }
+}
